with lines as (select id, service, level, latency_ms, status_code, attr_key, attr_value from app_logs lateral view outer explode(context) li as attr_key, attr_value) select *, sum(status_code) over (partition by level, attr_key) as level_sum_status_code, rank() over (partition by level, attr_key order by latency_ms desc) as latency_ms_rank, cume_dist() over (order by status_code) as status_code_cume_dist from lines;
